create function public.set_config(p_actor uuid,p_bank jsonb,p_refund text,p_support text,p_retention boolean) returns void language plpgsql security definer set search_path='' as $$declare c uuid;begin perform public.require_admin(p_actor,true);select id into strict c from public.site_config limit 1 for update;if length(p_refund)<20 or length(p_support)<5 or not p_bank ?& array['bank_name','account_number','beneficiary'] then raise exception 'config invalid';end if;update public.site_config set bank=p_bank,refund_policy=p_refund,support=p_support,retention_approved=p_retention,release_verified=false,updated_at=now() where id=c;insert into public.audit_events(actor,action,resource_id,changed_fields) values(p_actor,'config_changed_release_locked',c,array['bank','refund_policy','support','retention_approved']);end$$;
create function public.set_package(p_actor uuid,p_code text,p_price integer,p_hours integer,p_version integer) returns void language plpgsql security definer set search_path='' as $$begin perform public.require_admin(p_actor,true);if p_price<1000 or p_price>10000000 or p_hours<1 or p_hours>720 then raise exception 'package invalid';end if;update public.service_packages set price_vnd=p_price,delivery_hours=p_hours,version=version+1,updated_at=now() where code=p_code and version=p_version;if not found then raise exception 'version conflict';end if;update public.site_config set release_verified=false;insert into public.audit_events(actor,action,changed_fields) values(p_actor,'package_changed_release_locked',array['price_vnd','delivery_hours','version']);end$$;
create function public.public_gallery() returns table(id uuid,bucket text,storage_key text,mime text) language sql security definer set search_path='' as $$select m.id,a.bucket,a.storage_key,a.mime from public.public_media m join public.attachments a on a.id=m.asset_id join public.consent_events c on c.id=m.consent_id where m.state='published' and m.platform='website_public_gallery' and a.release_state='released' and a.classification='public_derivative' and c.granted and c.age_band='18+' and c.asset_hash=a.checksum and c.asset_version=a.asset_version and c.event_seq=(select max(event_seq) from public.consent_events where asset_id=a.id and scope=m.platform)$$;
revoke all on function public.set_config(uuid,jsonb,text,text,boolean),public.set_package(uuid,text,integer,integer,integer),public.public_gallery() from public,anon,authenticated;
grant execute on function public.set_config(uuid,jsonb,text,text,boolean),public.set_package(uuid,text,integer,integer,integer),public.public_gallery() to service_role;
